<template>
  <div class="plugin-shell">
    <section class="hero-panel">
      <div>
        <p class="eyebrow">二九对接站插件</p>
        <h1>第三方站点接入工作台</h1>
        <p class="hero-desc">
          当前页面负责价格读取、下单、订单跟踪和退款申请，实际请求先打本地 PHP 插件，再由插件转发到对接站网关。
        </p>
      </div>
      <div class="hero-actions">
        <el-button type="primary" :loading="loading.bootstrap" @click="bootstrap">刷新配置</el-button>
        <el-button text :loading="loading.balance" @click="loadHostBalance">刷新余额</el-button>
        <el-tag :type="connected ? 'success' : 'danger'">{{ connected ? '网关已连接' : '网关未连接' }}</el-tag>
      </div>
    </section>

    <section class="overview-grid">
      <article class="metric-card">
        <span>站点</span>
        <strong>{{ bootstrapState.siteName || '未绑定' }}</strong>
      </article>
      <article class="metric-card">
        <span>测试站用户</span>
        <strong>{{ bootstrapState.currentUserName || '未登录' }}</strong>
      </article>
      <article class="metric-card">
        <span>站点 UID</span>
        <strong>{{ bootstrapState.currentUserUid || '-' }}</strong>
      </article>
      <article class="metric-card">
        <span>站点 UUID</span>
        <strong>{{ bootstrapState.currentUserUuid || '-' }}</strong>
      </article>
      <article class="metric-card">
        <span>站点余额</span>
        <strong>{{ formatMoney(bootstrapState.currentUserMoney) }}</strong>
      </article>
      <article class="metric-card">
        <span>App Key</span>
        <strong>{{ bootstrapState.appKey || '-' }}</strong>
      </article>
      <article class="metric-card">
        <span>订单数</span>
        <strong>{{ orders.length }}</strong>
      </article>
      <article class="metric-card">
        <span>最后同步</span>
        <strong>{{ bootstrapState.serverTimeLabel || '-' }}</strong>
      </article>
    </section>

    <div class="content-grid">
      <section class="content-card">
        <header class="card-header">
          <div>
            <h2>下单面板</h2>
            <p>学校、平台、公里数与晨跑模式都来自主站统一口径。</p>
          </div>
          <el-button text :loading="loading.prices" @click="openPriceDialog">查看价格列表</el-button>
        </header>

        <el-form :model="form" label-position="top" class="order-form">
          <el-form-item label="学校">
            <el-select v-model="form.school_name" filterable placeholder="请选择或输入学校名称搜索">
              <el-option v-for="school in schools" :key="school.id" :label="school.name" :value="school.name" />
            </el-select>
          </el-form-item>
          <el-form-item label="平台">
            <el-select v-model="form.platform" :disabled="isPlatformForced" placeholder="请选择平台">
              <el-option v-for="platform in platforms" :key="platform" :label="platform" :value="platform" />
            </el-select>
          </el-form-item>
          <el-form-item label="账号">
            <el-input v-model="form.account" placeholder="手机号或账号" />
          </el-form-item>
          <el-form-item label="密码">
            <el-input v-model="form.password" type="password" show-password placeholder="密码" />
          </el-form-item>
          <el-form-item label="公里数">
            <el-input-number v-model="form.target_km" :min="1" :max="20" :step="0.5" style="width: 100%" />
          </el-form-item>
          <el-form-item label="跑步模式">
            <div class="mode-row">
              <el-switch
                v-model="form.is_morning_run"
                :disabled="Boolean(currentSchoolConfig && !currentSchoolConfig.morning_run_enabled)"
                active-text="晨跑"
                inactive-text="日常跑"
              />
              <el-tag type="info">{{ form.is_morning_run ? '晨跑' : '日常跑' }}</el-tag>
            </div>
          </el-form-item>
          <el-form-item v-if="currentSchoolConfig && estimatedPrice > 0" label="预计扣费">
            <div class="mode-row">
              <strong style="color: var(--el-color-danger); font-size: 18px;">{{ formatMoney(estimatedPrice) }}</strong>
              <el-tag type="warning">
                单价：{{ form.is_morning_run ? currentSchoolConfig.morning_unit_price : currentSchoolConfig.daily_unit_price }} 元/km
              </el-tag>
            </div>
          </el-form-item>
          <el-button type="primary" size="large" :loading="loading.submit" @click="submitOrder">提交订单</el-button>
        </el-form>
      </section>
    </div>

    <el-dialog v-model="priceDialogVisible" title="学校价格列表" width="960px">
      <el-table v-loading="loading.prices" :data="prices" stripe empty-text="暂无价格数据" max-height="520">
        <el-table-column prop="school_name" label="学校" min-width="180" />
        <el-table-column prop="platforms" label="平台" min-width="180">
          <template #default="{ row }">
            {{ row.platforms.length ? row.platforms.join(' / ') : '-' }}
          </template>
        </el-table-column>
        <el-table-column prop="daily_unit_price" label="日常跑单价" min-width="120" />
        <el-table-column prop="morning_unit_price" label="晨跑单价" min-width="120" />
      </el-table>
    </el-dialog>

    <section class="content-card">
      <header class="card-header">
        <div>
          <h2>订单列表</h2>
          <p>插件本地记录会定时同步网关状态，你也可以手动刷新。</p>
        </div>
        <el-button type="primary" plain @click="loadOrders">刷新订单</el-button>
      </header>

      <el-table :data="orders" stripe empty-text="暂无订单">
        <el-table-column prop="trace_id" label="Trace ID" min-width="180" />
        <el-table-column label="下单用户" min-width="180">
          <template #default="{ row }">
            {{ row.host_display_name || row.host_username || `UID:${row.host_user_uid || 0}` }}
          </template>
        </el-table-column>
        <el-table-column prop="school_name" label="学校" min-width="120" />
        <el-table-column prop="platform" label="平台" min-width="110" />
        <el-table-column prop="target_km" label="公里数" width="90" />
        <el-table-column prop="status" label="状态" width="130">
          <template #default="{ row }">
            <el-tag :type="statusTagType(row.status)">{{ row.status }}</el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="status_message" label="状态说明" min-width="180" />
        <el-table-column prop="updated_at" label="更新时间" min-width="180">
          <template #default="{ row }">
            {{ formatDisplayTime(row.updated_at) }}
          </template>
        </el-table-column>
        <el-table-column label="操作" width="220">
          <template #default="{ row }">
            <div class="table-actions">
              <el-button text @click="refreshStatus(row.trace_id)">查状态</el-button>
              <el-button text type="danger" @click="refundOrder(row.trace_id)" :disabled="!canRefund(row.status)">退款</el-button>
            </div>
          </template>
        </el-table-column>
      </el-table>
    </section>

    <TicketPanel
      :orders="orders"
      :current-user-name="bootstrapState.currentUserName"
      :current-user-uid="bootstrapState.currentUserUid"
    />
  </div>
</template>

<script setup lang="ts">
import { ElMessage } from 'element-plus'
import { computed, onMounted, reactive, ref, watch } from 'vue'
import TicketPanel from '../components/TicketPanel.vue'
import { getErrorMessage, request, throwApiError } from '../lib/api'

type BootstrapData = {
  appKey: string
  siteName: string
  currentUserName: string
  currentUserUid: number
  currentUserUuid: string
  currentUserMoney: number
  serverTimeLabel: string
}

type PriceRow = {
  id?: string
  school_name: string
  platforms: string[]
  daily_unit_price: number
  morning_unit_price: number
}

type OrderRow = {
  trace_id: string
  source_order_id?: string
  host_user_uid: number
  host_username: string
  host_display_name: string
  host_user_uuid: string
  account?: string
  school_name: string
  platform: string
  target_km: number
  status: string
  status_message: string
  updated_at: string
}

type SchoolRow = {
  id: string
  name: string
  platform: string
  forcePlatform: boolean
  morning_run_enabled: boolean
  daily_unit_price: number
  morning_unit_price: number
}

type BootstrapPayload = {
  app_key?: string
  site_name?: string
  current_user?: {
    uid?: number | string
    uuid?: string
    username?: string
    display_name?: string
    money?: number | string
  }
  server_time?: string
}

type HostProfilePayload = {
  uid?: number | string
  uuid?: string
  username?: string
  display_name?: string
  money?: number | string
}

type PricesPayload = {
  prices?: Array<Record<string, unknown>>
}

const loading = reactive({
  bootstrap: false,
  submit: false,
  balance: false,
  prices: false,
})

const bootstrapState = reactive<BootstrapData>({
  appKey: '',
  siteName: '',
  currentUserName: '',
  currentUserUid: 0,
  currentUserUuid: '',
  currentUserMoney: 0,
  serverTimeLabel: '',
})

const schools = ref<SchoolRow[]>([])
const platforms = ref<string[]>([])
const prices = ref<PriceRow[]>([])
const orders = ref<OrderRow[]>([])
const priceDialogVisible = ref(false)

const form = reactive({
  school_name: '',
  platform: '',
  account: '',
  password: '',
  target_km: 2,
  is_morning_run: false,
})

const connected = computed(() => Boolean(bootstrapState.appKey))
const currentSchoolConfig = computed(() => {
  return schools.value.find((item) => item.name === form.school_name) ?? null
})
const isPlatformForced = computed(() => Boolean(currentSchoolConfig.value?.forcePlatform && currentSchoolConfig.value?.platform))
const estimatedPrice = computed(() => {
  if (!currentSchoolConfig.value || !form.target_km) {
    return 0
  }
  const unitPrice = form.is_morning_run
    ? Number(currentSchoolConfig.value.morning_unit_price || 0)
    : Number(currentSchoolConfig.value.daily_unit_price || 0)
  return unitPrice * Number(form.target_km || 0)
})

function statusTagType(status: string) {
  if (status === 'approved') return 'success'
  if (status === 'pending_delivery' || status === 'pending_review' || status === 'refund_pending') return 'warning'
  if (status === 'rejected') return 'danger'
  return 'info'
}

function canRefund(status: string) {
  return status === 'approved'
}

function formatDisplayTime(value: string) {
  if (!value) return '-'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return value
  return date.toLocaleString('zh-CN', { hour12: false })
}

function formatMoney(value: number) {
  return `¥${Number(value || 0).toFixed(2)}`
}

async function bootstrap() {
  loading.bootstrap = true
  try {
    const data = await request<BootstrapPayload>('bootstrap')
    const payload = data.data || {}
    const currentUser = payload.current_user || {}
    bootstrapState.appKey = payload.app_key || ''
    bootstrapState.siteName = payload.site_name || ''
    bootstrapState.currentUserName = currentUser.display_name || currentUser.username || '未登录'
    bootstrapState.currentUserUid = Number(currentUser.uid || 0)
    bootstrapState.currentUserUuid = String(currentUser.uuid || '')
    bootstrapState.currentUserMoney = Number(currentUser.money || 0)
    bootstrapState.serverTimeLabel = formatDisplayTime(payload.server_time || '')
    await Promise.all([loadCatalog(), loadOrders()])
  } catch (error) {
    ElMessage.error(getErrorMessage(error, '初始化失败'))
    console.error(error)
  } finally {
    loading.bootstrap = false
  }
}

async function loadHostBalance(showMessage = false) {
  loading.balance = true
  try {
    const result = await request<HostProfilePayload>('host_profile')
    const payload = result.data || {}
    bootstrapState.currentUserUid = Number(payload.uid || 0)
    bootstrapState.currentUserUuid = String(payload.uuid || '')
    bootstrapState.currentUserMoney = Number(payload.money || 0)
    if (!bootstrapState.currentUserName) {
      bootstrapState.currentUserName = payload.display_name || payload.username || '未登录'
    }
    if (showMessage) {
      ElMessage.success(`当前余额：${formatMoney(bootstrapState.currentUserMoney)}`)
    }
  } catch (error) {
    ElMessage.error(getErrorMessage(error, '余额读取失败'))
    console.error(error)
  } finally {
    loading.balance = false
  }
}

async function loadCatalog() {
  const [schoolRes, platformRes] = await Promise.all([
    request('schools'),
    request('platforms'),
  ])
  const schoolCatalog = Array.isArray(schoolRes.data) ? schoolRes.data : []
  schools.value = schoolCatalog.map((item: Record<string, unknown>) => ({
    id: String(item.id || ''),
    name: String(item.name || ''),
    platform: String(item.platform || ''),
    forcePlatform: Boolean(item.forcePlatform),
    morning_run_enabled: Boolean(item.morningRunEnabled),
    daily_unit_price: Number(item.daily_unit_price ?? item.dailyUnitPrice ?? 0),
    morning_unit_price: Number(item.morning_unit_price ?? item.morningUnitPrice ?? 0),
  }))
  platforms.value = Array.isArray(platformRes.data) ? platformRes.data.map((item: unknown) => String(item)) : []
  if (!form.school_name && schools.value[0]) form.school_name = schools.value[0].name
  syncPlatformWithSchool()
}

async function loadPriceList(forceRefresh = false) {
  if (!forceRefresh && prices.value.length > 0) {
    return
  }

  loading.prices = true
  try {
    const result = await request<PricesPayload>('prices')
    const priceRows = Array.isArray(result.data?.prices) ? result.data.prices : []
    prices.value = priceRows.map((item: Record<string, unknown>) => ({
      id: String(item.id || item.school_name || ''),
      school_name: String(item.school_name || ''),
      platforms: Array.isArray(item.platforms) ? item.platforms.map((platform) => String(platform)) : [],
      daily_unit_price: Number(item.daily_unit_price ?? 0),
      morning_unit_price: Number(item.morning_unit_price ?? 0),
    }))
  } finally {
    loading.prices = false
  }
}

async function openPriceDialog() {
  try {
    await loadPriceList()
    priceDialogVisible.value = true
  } catch (error) {
    ElMessage.error(getErrorMessage(error, '价格列表读取失败'))
    console.error(error)
  }
}

function syncPlatformWithSchool() {
  if (!platforms.value.length) {
    form.platform = currentSchoolConfig.value?.platform || ''
    return
  }
  const currentSchool = currentSchoolConfig.value
  if (!currentSchool) {
    if (!platforms.value.includes(form.platform)) {
      form.platform = platforms.value[0]
    }
    return
  }
  if (currentSchool.forcePlatform && currentSchool.platform) {
    form.platform = currentSchool.platform
    return
  }
  if (currentSchool.platform && !form.platform) {
    form.platform = currentSchool.platform
    return
  }
  if (!platforms.value.includes(form.platform)) {
    form.platform = currentSchool.platform && platforms.value.includes(currentSchool.platform)
      ? currentSchool.platform
      : platforms.value[0]
  }
}

async function refreshCatalogSnapshot(silent = true) {
  try {
    await loadCatalog()
  } catch (error) {
    console.error(error)
    if (!silent) {
      ElMessage.error(getErrorMessage(error, '学校和价格读取失败'))
    }
  }
}

async function loadOrders() {
  const result = await request<OrderRow[]>('orders')
  orders.value = Array.isArray(result.data) ? result.data : []
}

function scheduleOrderStatusPolling(traceId: string, maxAttempts = 90) {
  let attempts = 0
  const tick = async () => {
    attempts += 1
    try {
      const result = await request('order_status', 'get', { trace_id: traceId })
      const order = (result.data as { order?: OrderRow } | undefined)?.order
      await loadOrders()
      if (order?.status && order.status !== 'pending_delivery') {
        if (!['pending_review', 'refund_pending'].includes(order.status)) {
          await loadHostBalance(false)
        }
        return
      }
      if (attempts < maxAttempts) {
        window.setTimeout(tick, Math.max(1500, Number(result.next_poll_after_ms || 3000)))
      }
    } catch (error) {
      console.error(error)
      if (attempts < maxAttempts) {
        window.setTimeout(tick, 3000)
      }
    }
  }
  window.setTimeout(tick, 1600)
}

async function submitOrder() {
  if (!form.school_name || !form.platform || !form.account || !form.password || form.target_km <= 0) {
    ElMessage.warning('请先完整填写学校、平台、账号、密码和公里数')
    return
  }
  loading.submit = true
  try {
    const currentEstimatedPrice = estimatedPrice.value
    await Promise.all([refreshCatalogSnapshot(false), loadHostBalance(false)])
    const latestEstimatedPrice = estimatedPrice.value
    if (Math.abs(latestEstimatedPrice - currentEstimatedPrice) >= 0.000001) {
      ElMessage.warning(`主站价格已变更，当前预计扣费已更新为 ${formatMoney(latestEstimatedPrice)}，请确认后重新提交`)
      return
    }
    if (latestEstimatedPrice > Number(bootstrapState.currentUserMoney || 0)) {
      ElMessage.warning(`站点余额不足，当前余额 ${formatMoney(bootstrapState.currentUserMoney)}，预计扣费 ${formatMoney(latestEstimatedPrice)}`)
      return
    }

    const result = await request('create_order', 'post', {
      ...form,
      run_mode_enabled: true,
      run_mode_text: form.is_morning_run ? '晨跑' : '日常跑',
    })
    if (!result.trace_id) {
      throwApiError(result, '下单未返回 trace_id')
    }
    ElMessage.success(result.message ? `${result.message}：${result.trace_id}` : `提交成功：${result.trace_id}`)
    await Promise.all([loadOrders(), loadHostBalance()])
    scheduleOrderStatusPolling(String(result.trace_id))
  } catch (error) {
    ElMessage.error(getErrorMessage(error, '提交失败'))
    console.error(error)
  } finally {
    loading.submit = false
  }
}

async function refreshStatus(traceId: string) {
  try {
    const result = await request('order_status', 'get', { trace_id: traceId })
    ElMessage.success(result.message || '状态已刷新')
    await loadOrders()
  } catch (error) {
    ElMessage.error(getErrorMessage(error, '状态刷新失败'))
    console.error(error)
  }
}

async function refundOrder(traceId: string) {
  try {
    const result = await request('refund_order', 'post', { trace_id: traceId })
    ElMessage.success(result.message || '退款申请已提交')
    await Promise.all([loadOrders(), loadHostBalance()])
  } catch (error) {
    ElMessage.error(getErrorMessage(error, '退款失败'))
    console.error(error)
  }
}

onMounted(() => {
  bootstrap()
})

watch(() => form.school_name, () => {
  syncPlatformWithSchool()
  if (form.is_morning_run && currentSchoolConfig.value && !currentSchoolConfig.value.morning_run_enabled) {
    form.is_morning_run = false
  }
})
</script>
