<template>
  <section class="content-card ticket-panel">
    <header class="card-header">
      <div>
        <h2>工单中心</h2>
        <p>普通用户只会看到自己上报的工单，关联订单时仅允许选择自己可见的订单。</p>
      </div>
      <el-button type="primary" plain :loading="loading.list" @click="loadTickets">刷新工单</el-button>
    </header>

    <div class="ticket-create-grid">
      <el-form :model="form" label-position="top" class="ticket-form">
        <el-form-item label="关联订单">
          <el-select v-model="form.linked_trace_id" clearable filterable placeholder="可选，选择自己上传的订单">
            <el-option
              v-for="order in props.orders"
              :key="order.trace_id"
              :label="formatOrderOption(order)"
              :value="order.trace_id"
            />
          </el-select>
        </el-form-item>
        <el-form-item label="异常类型">
          <el-select v-model="form.fault_type" placeholder="请选择异常类型">
            <el-option v-for="item in faultTypeOptions" :key="item" :label="item" :value="item" />
          </el-select>
        </el-form-item>
        <el-form-item label="账号">
          <el-input v-model="form.account" placeholder="可手填，不关联订单时建议填写" />
        </el-form-item>
        <el-form-item label="密码">
          <el-input v-model="form.password" type="password" show-password placeholder="可选" />
        </el-form-item>
        <el-form-item label="学校">
          <el-input v-model="form.school" placeholder="可手填，不关联订单时建议填写" />
        </el-form-item>
        <el-form-item label="问题描述">
          <el-input v-model="form.message" type="textarea" :rows="4" resize="vertical" placeholder="请描述具体问题" />
        </el-form-item>
        <div class="ticket-create-actions">
          <el-button type="primary" :loading="loading.create" @click="createTicket">提交工单</el-button>
        </div>
      </el-form>
    </div>

    <el-table :data="tickets" stripe empty-text="暂无工单">
      <el-table-column prop="id" label="工单ID" min-width="180" />
      <el-table-column label="上传人" min-width="160">
        <template #default="{ row }">
          {{ row.source_host_display_name || row.source_host_username || `UID:${row.source_host_user_uid || 0}` }}
        </template>
      </el-table-column>
      <el-table-column label="关联订单" min-width="200">
        <template #default="{ row }">
          {{ row.source_trace_id || row.order_id || row.source_order_id || '-' }}
        </template>
      </el-table-column>
      <el-table-column prop="fault_type" label="异常类型" min-width="120" />
      <el-table-column prop="status" label="状态" width="110">
        <template #default="{ row }">
          <el-tag :type="statusTagType(row.status)">{{ row.status || '-' }}</el-tag>
        </template>
      </el-table-column>
      <el-table-column prop="last_message_at" label="最后更新" min-width="180">
        <template #default="{ row }">
          {{ formatDisplayTime(row.last_message_at || row.updated_at) }}
        </template>
      </el-table-column>
      <el-table-column label="操作" width="160">
        <template #default="{ row }">
          <el-button text @click="openTicketDetail(row)">查看详情</el-button>
        </template>
      </el-table-column>
    </el-table>

    <el-dialog v-model="detailVisible" title="工单详情" width="860px">
      <template v-if="activeTicket">
        <el-descriptions :column="2" border class="ticket-detail-meta">
          <el-descriptions-item label="工单ID">{{ activeTicket.id }}</el-descriptions-item>
          <el-descriptions-item label="状态">{{ activeTicket.status || '-' }}</el-descriptions-item>
          <el-descriptions-item label="异常类型">{{ activeTicket.fault_type || '-' }}</el-descriptions-item>
          <el-descriptions-item label="关联订单">{{ activeTicket.source_trace_id || activeTicket.order_id || activeTicket.source_order_id || '-' }}</el-descriptions-item>
          <el-descriptions-item label="账号">{{ activeTicket.account || '-' }}</el-descriptions-item>
          <el-descriptions-item label="学校">{{ activeTicket.school || '-' }}</el-descriptions-item>
        </el-descriptions>

        <div class="conversation-box" v-loading="loading.detail">
          <div v-if="messages.length" class="conversation-list">
            <div
              v-for="item in messages"
              :key="item.id || `${item.sender_role}-${item.created_at}-${item.message}`"
              class="conversation-item"
              :class="`role-${item.sender_role || 'system'}`"
            >
              <div class="conversation-header">
                <span>{{ item.sender_name || item.sender_role || '系统' }}</span>
                <span>{{ formatDisplayTime(item.created_at || '') }}</span>
              </div>
              <div class="conversation-message">{{ item.message || '-' }}</div>
            </div>
          </div>
          <el-empty v-else description="暂无对话记录" />
        </div>

        <el-input
          v-model="replyMessage"
          type="textarea"
          :rows="4"
          resize="vertical"
          placeholder="输入回复内容"
          :disabled="activeTicket.status === '完结'"
        />
        <div class="ticket-detail-actions">
          <el-button @click="reloadDetail">刷新</el-button>
          <el-button type="primary" :loading="loading.reply" :disabled="activeTicket.status === '完结'" @click="replyTicket">
            发送回复
          </el-button>
        </div>
      </template>
    </el-dialog>
  </section>
</template>

<script setup lang="ts">
import { ElMessage } from 'element-plus'
import { onMounted, reactive, ref, watch } from 'vue'
import { getErrorMessage, request } from '../lib/api'

type OrderRow = {
  trace_id: string
  source_order_id?: string
  account?: string
  school_name?: string
}

type TicketRow = {
  id: string
  order_id?: string
  fault_type?: string
  account?: string
  school?: string
  status?: string
  updated_at?: string
  last_message_at?: string
  source_trace_id?: string
  source_order_id?: string
  source_host_user_uid?: number
  source_host_username?: string
  source_host_display_name?: string
}

type TicketMessage = {
  id?: string
  sender_role?: string
  sender_name?: string
  message?: string
  created_at?: string
}

const props = defineProps<{
  orders: OrderRow[]
  currentUserUid: number
  currentUserName: string
}>()

const loading = reactive({
  list: false,
  create: false,
  detail: false,
  reply: false,
})

const faultTypeOptions = ['账密错误', '学校错误', '缺少人脸', '人脸错误', '账号封禁', '他人登录', '双线下单']

const form = reactive({
  linked_trace_id: '',
  fault_type: '账密错误',
  account: '',
  password: '',
  school: '',
  message: '',
})

const tickets = ref<TicketRow[]>([])
const detailVisible = ref(false)
const activeTicket = ref<TicketRow | null>(null)
const messages = ref<TicketMessage[]>([])
const replyMessage = ref('')

function formatDisplayTime(value: string) {
  if (!value) return '-'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return value
  return date.toLocaleString('zh-CN', { hour12: false })
}

function formatOrderOption(order: OrderRow) {
  return [order.trace_id, order.school_name || '', order.account || ''].filter(Boolean).join(' | ')
}

function statusTagType(status?: string) {
  if (status === '待处理') return 'warning'
  if (status === '处理中') return 'primary'
  if (status === '完结') return 'success'
  return 'info'
}

async function loadTickets() {
  if (props.currentUserUid <= 0) return
  loading.list = true
  try {
    const result = await request<TicketRow[]>('tickets')
    tickets.value = Array.isArray(result.data) ? result.data : []
  } catch (error) {
    ElMessage.error(getErrorMessage(error, '工单读取失败'))
  } finally {
    loading.list = false
  }
}

async function openTicketDetail(row: TicketRow) {
  detailVisible.value = true
  activeTicket.value = { ...row }
  replyMessage.value = ''
  await reloadDetail()
}

async function reloadDetail() {
  if (!activeTicket.value?.id) return
  loading.detail = true
  try {
    const result = await request<{ ticket?: TicketRow; messages?: TicketMessage[] }>('ticket_detail', 'get', {
      ticket_id: activeTicket.value.id,
    })
    const payload = result.data || {}
    activeTicket.value = payload.ticket ? { ...payload.ticket } : activeTicket.value
    messages.value = Array.isArray(payload.messages) ? payload.messages : []
  } catch (error) {
    ElMessage.error(getErrorMessage(error, '工单详情读取失败'))
  } finally {
    loading.detail = false
  }
}

async function reloadDetailUntilMessage(expectedMessage: string, maxAttempts = 8) {
  for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
    await reloadDetail()
    if (!expectedMessage || messages.value.some((item) => (item.message || '').includes(expectedMessage))) {
      return
    }
    await new Promise((resolve) => window.setTimeout(resolve, 800))
  }
}

async function createTicket() {
  if (!form.fault_type || !form.message.trim()) {
    ElMessage.warning('异常类型和问题描述不能为空')
    return
  }
  loading.create = true
  try {
    await request('create_ticket', 'post', {
      linked_trace_id: form.linked_trace_id,
      fault_type: form.fault_type,
      account: form.account,
      password: form.password,
      school: form.school,
      message: form.message,
    })
    ElMessage.success('工单创建成功')
    form.message = ''
    form.password = ''
    await loadTickets()
  } catch (error) {
    ElMessage.error(getErrorMessage(error, '工单创建失败'))
  } finally {
    loading.create = false
  }
}

async function replyTicket() {
  if (!activeTicket.value?.id || !replyMessage.value.trim()) {
    ElMessage.warning('回复内容不能为空')
    return
  }
  loading.reply = true
  try {
    const sentMessage = replyMessage.value.trim()
    await request('reply_ticket', 'post', {
      ticket_id: activeTicket.value.id,
      message: sentMessage,
    })
    replyMessage.value = ''
    ElMessage.success('回复成功')
    await loadTickets()
    await reloadDetailUntilMessage(sentMessage)
  } catch (error) {
    ElMessage.error(getErrorMessage(error, '工单回复失败'))
  } finally {
    loading.reply = false
  }
}

watch(
  () => form.linked_trace_id,
  (traceId) => {
    if (!traceId) return
    const order = props.orders.find((item) => item.trace_id === traceId)
    if (!order) return
    if (!form.account) {
      form.account = order.account || ''
    }
    if (!form.school) {
      form.school = order.school_name || ''
    }
  },
)

watch(
  () => props.currentUserUid,
  (value) => {
    if (value > 0) {
      void loadTickets()
    }
  },
  { immediate: true },
)

onMounted(() => {
  if (props.currentUserUid > 0) {
    void loadTickets()
  }
})
</script>

